CREATE TABLE empenhos_importacoes (id INTEGER PRIMARY KEY AUTOINCREMENT, periodo TEXT NOT NULL, descricao TEXT, arquivo TEXT, total_rows INTEGER DEFAULT 0, importado_em TEXT);
CREATE TABLE empenhos_linhas (id INTEGER PRIMARY KEY AUTOINCREMENT, importacao_id INTEGER NOT NULL REFERENCES empenhos_importacoes(id) ON DELETE CASCADE, dados TEXT NOT NULL);
CREATE TABLE fornecimento_dados (id INTEGER PRIMARY KEY AUTOINCREMENT, tipo TEXT NOT NULL, valor TEXT NOT NULL, criado_em TEXT DEFAULT (datetime('now', 'localtime')), UNIQUE(tipo, valor));
CREATE TABLE fornecimento_solicitacao_itens (id INTEGER PRIMARY KEY AUTOINCREMENT, solicitacao_id INTEGER NOT NULL REFERENCES fornecimento_solicitacoes(id) ON DELETE CASCADE, nome TEXT NOT NULL, desc TEXT DEFAULT '', qtd TEXT DEFAULT '', preco TEXT DEFAULT '');
CREATE TABLE fornecimento_solicitacoes (id INTEGER PRIMARY KEY AUTOINCREMENT, solicitante TEXT NOT NULL, empresa TEXT DEFAULT '', data TEXT NOT NULL, obs TEXT DEFAULT '', criado_em TEXT DEFAULT (datetime('now','localtime')), atualizado_em TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE kanban_attachment_contents (attachment_id INTEGER PRIMARY KEY REFERENCES kanban_attachments(id) ON DELETE CASCADE, content BLOB NOT NULL);
CREATE TABLE kanban_attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT NOT NULL REFERENCES kanban_tasks(id) ON DELETE CASCADE, file_name TEXT NOT NULL, mime_type TEXT DEFAULT 'application/octet-stream', file_size INTEGER DEFAULT 0, criado_em TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE kanban_tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT DEFAULT '', status TEXT DEFAULT 'todo', priority TEXT DEFAULT 'medium', concluido_em TEXT DEFAULT '', criado_em TEXT DEFAULT (datetime('now', 'localtime')), atualizado_em TEXT DEFAULT (datetime('now', 'localtime')), categoria TEXT DEFAULT '', data_vencimento TEXT DEFAULT '', responsavel TEXT DEFAULT '', valor REAL DEFAULT 0);
CREATE TABLE logs (id INTEGER PRIMARY KEY AUTOINCREMENT, acao TEXT NOT NULL, credor_id INTEGER, credor_nome TEXT, detalhes TEXT, data TEXT DEFAULT (datetime('now', 'localtime')), mudancas_json TEXT DEFAULT '{}', credor_departamento TEXT DEFAULT '', credor_cnpj TEXT DEFAULT '', FOREIGN KEY(credor_id) REFERENCES credores(id) ON DELETE SET NULL);
